 const update=()=>{scheduled=false;const anchor=innerHeight*.38;let best=0,distance=Infinity;sections.forEach((section,index)=>{const rect=section.getBoundingClientRect(),candidate=rect.top<=anchor&&rect.bottom>=anchor?0:Math.min(Math.abs(rect.top-anchor),Math.abs(rect.bottom-anchor));if(candidate<distance){best=index;distance=candidate}});active=best;const max=Math.max(1,document.documentElement.scrollHeight-innerHeight),ratio=Math.max(0,Math.min(1,scrollY/max));progress.style.transform=`scaleX(${ratio})`;count.textContent=`${active+1} / ${sections.length}`;title.textContent=label(sections[active],active);previous.disabled=active===0;next.disabled=active===sections.length-1;dock.dataset.scrolled=scrollY>Math.min(420,innerHeight*.55)?'true':'false';[...list.children].forEach((button,index)=>button.setAttribute('aria-current',index===active?'true':'false'))};
