 addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule,{passive:true});document.addEventListener('pointerdown',event=>{if(!menu.hidden&&!menu.contains(event.target)&&!menuButton.contains(event.target))closeMenu()});menu.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();closeMenu(true)}});root.addEventListener('click',event=>{if(event.target.closest('[data-guest-lang]'))requestAnimationFrame(()=>{refreshLanguage();update()})});
