function downloadCalendarEntry(entry,d){const start=new Date(`${entry.date||''}T${entry.time||'00:00'}:00`);if(Number.isNaN(start.getTime())){guestToast('This event does not have a valid date yet.');return}const end=new Date(start.getTime()+Math.max(30,Number(entry.durationMinutes||120))*60*1000),lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//E-invitation-website//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH','BEGIN:VEVENT',`UID:${crypto.randomUUID()}@e-invitation-website`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART:${icsLocal(start)}`,`DTEND:${icsLocal(end)}`,`SUMMARY:${icsEscape(entry.name||entry.names||'Invitation')}`,`DESCRIPTION:${icsEscape(entry.description||d.fields?.message||'')}`,`LOCATION:${icsEscape(entry.venue||'')}`,`URL:${icsEscape(publicShareUrl())}`,'END:VEVENT','END:VCALENDAR'];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\r\n')],{type:'text/calendar;charset=utf-8'}));a.download=`${String(entry.name||entry.names||'event').replace(/[^A-Za-z0-9_-]+/g,'-').replace(/^-|-$/g,'').toLowerCase()||'event'}.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
