function studioBrandMarkup(brand){if(!brand||(!brand.name&&!brand.logo&&!brand.hidePlatformBrand))return '<footer class="guest-platform-credit">Created with E-Invitation Platform</footer>';const logo=brand.logo&&safeSectionImageUrl(brand.logo)?`<img src="${esc(brand.logo)}" alt="${esc(brand.name||'Invitation studio')} logo" loading="lazy" decoding="async">`:'';const website=/^https:\/\//i.test(brand.website||'')?brand.website:'';const studio=brand.name?`<span>${esc(brand.name)}</span>`:'';const identity=website?`<a href="${esc(website)}" target="_blank" rel="noopener noreferrer">${logo}${studio}</a>`:`<span class="studio-brand-identity">${logo}${studio}</span>`;return `<footer class="guest-studio-brand" style="${/^#[0-9a-f]{6}$/i.test(brand.primaryColor||'')?`--studio-brand:${brand.primaryColor};`:''}${/^#[0-9a-f]{6}$/i.test(brand.accentColor||'')?`--studio-accent:${brand.accentColor};`:''}">${identity}${brand.hidePlatformBrand?'':'<small>Created with E-Invitation Platform</small>'}</footer>`}
