function sectionAnimationStyle(d,name){let defaults={hero:{preset:'fade-up',duration:900},gallery:{preset:'fade-up',duration:900},video:{preset:'soft-zoom',duration:900},countdown:{preset:'soft-zoom',duration:900},events:{preset:'fade-up',duration:900},schedule:{preset:'fade-up',duration:900},custom:{preset:'fade-up',duration:900},'guest-info':{preset:'fade-up',duration:900},venue:{preset:'fade-up',duration:900},contact:{preset:'fade-up',duration:900},rsvp:{preset:'fade-up',duration:900},wishes:{preset:'fade-up',duration:900}},setting=d.sectionAnimations?.[name]||defaults[name]||defaults.hero,animation=animationName(setting.preset);return animation?`animation-name:${animation};animation-duration:${Math.max(300,Math.min(3000,Number(setting.duration||900)))}ms`:'animation:none'}
