function featuredVideoMarkup(d,mode){let items=[];if(d.settings?.videoEnabled===true&&d.video?.url){let url=String(d.video.url||'');if(url.startsWith('/uploads/')||url.startsWith('/api/media/')||url.startsWith('/api/image/')||url.startsWith('/data/uploads/')||/^https?:\/\//i.test(url)||/^data:video\/(?:mp4|webm);base64,/i.test(url))items.push(`<video class="invitation-video" controls playsinline preload="metadata" src="${esc(url)}"></video>`)}const youtube=/^[\w-]{11}$/.test(d.youtubeId||'')&&d.settings?.musicSource==='youtube',display=d.settings?.youtubeDisplayMode||'background';if(youtube&&display!=='background'&&externalMediaAllowed){const featuredSrc=`https://www.youtube-nocookie.com/embed/${encodeURIComponent(d.youtubeId)}?rel=0&playsinline=1`;items.push(`<div class="external-video external-video-${esc(display)}"><iframe id="youtubeFeaturedPlayer" class="youtube-visible-player" src="${esc(featuredSrc)}" data-video-id="${esc(d.youtubeId)}" title="YouTube video" allow="encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><p class="external-media-fallback">${langText('If the video cannot be embedded,','ប្រសិនបើវីដេអូមិនអាចបង្ហាញបាន',mode)} <a href="https://youtu.be/${esc(d.youtubeId)}" target="_blank" rel="noopener noreferrer">${langText('open it on YouTube','បើកនៅលើ YouTube',mode)}</a>.</p></div>`)}else if(youtube&&display!=='background'&&!externalMediaAllowed){items.push(`<div class="external-media-consent-placeholder"><p>${langText('This YouTube video is waiting for your external-media consent.','វីដេអូ YouTube នេះកំពុងរង់ចាំការយល់ព្រមរបស់អ្នកសម្រាប់មេឌៀខាងក្រៅ។',mode)}</p></div>`)}if(!items.length)return'';return`<section class="video-section reveal" style="${combinedSectionStyle(d,'video')}"><h2>${langText('Featured Video','វីដេអូពិសេស',mode)}</h2>${items.join('')}</section>`}
function sectionVisualStyle(d,name){let v=d.sectionStyles?.[name];if(!v)return'';let r=[];if(v.backgroundEnabled&&/^#[0-9a-f]{6}$/i.test(v.background||''))r.push(`background-color:${v.background}`);let imageUrl=safeSectionImageUrl(v.backgroundImage);if(v.backgroundImageEnabled&&imageUrl){let overlay=Math.max(0,Math.min(80,Number(v.backgroundOverlay||0)))/100;r.push(`background-image:linear-gradient(rgba(0,0,0,${overlay}),rgba(0,0,0,${overlay})),url(&quot;${esc(imageUrl)}&quot;)`,`background-size:${v.backgroundSize==='contain'?'contain':'cover'}`,'background-position:center','background-repeat:no-repeat')}if(v.textColorEnabled&&/^#[0-9a-f]{6}$/i.test(v.textColor||''))r.push(`color:${v.textColor}`,`--section-text:${v.textColor}`);let radius=Math.max(0,Math.min(60,Number(v.radius||0)));if(radius)r.push(`border-radius:${radius}px`);return r.join(';')}
