function eventJourneyMarkup(d,mode){const events=(d.events||[]).filter(event=>event&&event.enabled!==false&&event.name);if(!events.length)return'';const timezone=String(d.timezone||'').trim();return`<section class="event-journey reveal" style="${combinedSectionStyle(d,'events')}"><h2>${langText('Events & ceremonies','កម្មវិធី និងពិធី',mode)}</h2>${timezone?`<p class="event-timezone">${langText('Timezone','តំបន់ពេលវេលា',mode)}: ${esc(timezone)}</p>`:''}<div class="event-journey-list">${events.map(event=>{const date=event.date?new Date(`${event.date}T${event.time||'00:00'}:00`):null,dateText=date&&!Number.isNaN(date.getTime())?date.toLocaleString(undefined,{dateStyle:'medium',timeStyle:event.time?'short':undefined}):[event.date,event.time].filter(Boolean).join(' '),map=/^https?:\/\//i.test(event.mapUrl||'')?`<a href="${esc(event.mapUrl)}" target="_blank" rel="noopener">${langText('Directions','ទិសដៅ',mode)}</a>`:'',calendar=event.date?`<button type="button" data-event-calendar="${esc(event.id||'')}">${langText('Add event to calendar','បន្ថែមកម្មវិធីទៅប្រតិទិន',mode)}</button>`:'';return`<article class="event-journey-card"><span class="event-type">${esc(event.type||'event')}</span><h3>${esc(event.name)}</h3>${dateText?`<p><strong>${esc(dateText)}</strong></p>`:''}${event.venue?`<p>${esc(event.venue)}</p>`:''}<div class="event-actions">${map}${calendar}</div></article>`}).join('')}</div></section>`}
function guestExperienceMarkup(d,mode){const info=d.guestExperience||{},items=[];if(info.dressCode)items.push([langText('Dress code','ការស្លៀកពាក់',mode),info.dressCode]);if(info.transport)items.push([langText('Transport','ការធ្វើដំណើរ',mode),info.transport]);if(info.accommodation)items.push([langText('Accommodation','កន្លែងស្នាក់នៅ',mode),info.accommodation]);if(info.note)items.push([langText('Guest note','សេចក្តីជូនដំណឹង',mode),info.note]);const gift=/^https?:\/\//i.test(info.giftLink||'')?`<a class="button-link" href="${esc(info.giftLink)}" target="_blank" rel="noopener noreferrer">${esc(info.giftLabel||langText('Gift registry','បញ្ជីអំណោយ',mode))}</a>`:'',payment=/^https?:\/\//i.test(info.paymentLink||'')?`<a class="button-link" href="${esc(info.paymentLink)}" target="_blank" rel="noopener noreferrer">${esc(info.paymentLabel||langText('Contribution / payment','ការចូលរួម / ការទូទាត់',mode))}</a>`:'';if(!items.length&&!gift&&!payment)return'';return`<section class="guest-information reveal" style="${combinedSectionStyle(d,'guest-info')}"><h2>${langText('Guest information','ព័ត៌មានសម្រាប់ភ្ញៀវ',mode)}</h2><div class="guest-information-grid">${items.map(([label,value])=>`<article><strong>${label}</strong><p>${esc(value)}</p></article>`).join('')}</div>${gift||payment?`<div class="guest-information-actions">${gift}${payment}</div>`:''}</section>`}
function customBlocksMarkup(d,mode){let blocks=(d.customBlocks||[]).filter(b=>b.enabled!==false);if(!blocks.length)return'';let layout=esc(d.sectionLayouts?.custom||'cards');return`<div class="custom-blocks custom-layout-${layout} reveal" style="${combinedSectionStyle(d,'custom')}">${blocks.map(b=>`<section class="custom-info-block block-${esc(b.type||'custom')}"><div class="block-icon">${b.type==='story'?'♥':b.type==='dress-code'?'✦':b.type==='note'?'!':b.type==='quote'?'“':b.type==='accommodation'?'⌂':b.type==='gift'?'◇':'◇'}</div><h2>${langText(b.heading||blockLabel(b.type),b.headingKm||b.heading||blockLabel(b.type),mode)}</h2><p>${langText(b.body||'',b.bodyKm||b.body||'',mode)}</p></section>`).join('')}</div>`}
function orderedPhotos(d){let objects=d.objects||{},photos=Object.entries(objects).filter(([,o])=>o.type==='image'&&o.src&&o.showInGallery!==false),order=Array.isArray(d.galleryOrder)?d.galleryOrder:[];return photos.sort(([aId,a],[bId,b])=>{let ai=order.indexOf(aId),bi=order.indexOf(bId);if(ai>=0||bi>=0)return(ai<0?9999:ai)-(bi<0?9999:bi);return Number(a.zIndex||0)-Number(b.zIndex||0)}).map(([id,photo])=>({id,...photo}))}
function galleryMarkup(d){if(d.settings?.galleryEnabled===false)return'';if(d.galleryProtection?.enabled&&d.galleryProtection?.locked)return`<section class="photo-gallery gallery-locked reveal" style="${combinedSectionStyle(d,'gallery')}" aria-label="Protected photo gallery"><div class="gallery-lock-card"><span aria-hidden="true">🔒</span><h2>${langText('Private photo gallery','វិចិត្រសាលរូបថតឯកជន',d.languageMode||'both')}</h2><p>${langText('Enter the gallery password to view these photos.','បញ្ចូលពាក្យសម្ងាត់វិចិត្រសាលដើម្បីមើលរូបថតទាំងនេះ។',d.languageMode||'both')}</p><form id="galleryUnlockForm"><label>${langText('Gallery password','ពាក្យសម្ងាត់វិចិត្រសាល',d.languageMode||'both')}<input name="password" type="password" required minlength="8" autocomplete="current-password"></label><button class="primary">${langText('Open gallery','បើកវិចិត្រសាល',d.languageMode||'both')}</button><p class="hint" data-gallery-error></p></form></div></section>`;let photos=orderedPhotos(d);if(!photos.length)return'';return`<section class="photo-gallery gallery-${esc(d.galleryStyle||'grid')} reveal" style="${combinedSectionStyle(d,'gallery')}" aria-label="Photo gallery">${photos.map((photo,index)=>{let animation=animationName(photo.animation),duration=Math.max(300,Math.min(3000,+(photo.duration||900))),delay=Math.min(index*.12,.72);return`<figure class="gallery-photo"><img src="${esc(photo.src)}"${responsiveImageAttrs(photo)} alt="${esc(photo.alt||`Celebration photo ${index+1}`)}" loading="lazy" decoding="async" class="reveal" style="animation-name:${animation};animation-duration:${duration}ms;animation-delay:${delay}s;object-fit:${esc(photo.imageFit||'cover')};object-position:${Number(photo.imagePositionX??50)}% ${Number(photo.imagePositionY??50)}%;filter:${imageFilterStyle(photo)}">${photo.caption?`<figcaption>${esc(photo.caption)}</figcaption>`:''}</figure>`}).join('')}</section>`}
function normalizedTelegram(value){let raw=String(value||'').trim();if(!raw)return'';if(/^https:\/\/t\.me\/[A-Za-z0-9_]{5,}$/i.test(raw))return raw;let username=raw.replace(/^@/,'');return/^[A-Za-z0-9_]{5,}$/.test(username)?`https://t.me/${username}`:''}
function contactMarkup(d,mode){if(d.settings?.contactEnabled===false)return'';let phone=String(d.contactPhone||'').trim(),telegram=normalizedTelegram(d.contactTelegram),phoneHref=/^[+0-9() .-]{5,30}$/.test(phone)?`tel:${phone.replace(/[^+0-9]/g,'')}`:'';if(!phoneHref&&!telegram)return'';return`<section class="contact-section reveal" style="${combinedSectionStyle(d,'contact')}"><h2>${langText('Contact the hosts','ទំនាក់ទំនងម្ចាស់កម្មវិធី',mode)}</h2><div class="contact-actions">${phoneHref?`<a href="${esc(phoneHref)}">☎ ${langText('Call','ទូរស័ព្ទ',mode)}</a>`:''}${telegram?`<a href="${esc(telegram)}" target="_blank" rel="noopener">✈ Telegram</a>`:''}</div></section>`}
